UPDATE cliente SET nombre=#{nombre}, apellido_paterno=#{apellidoPaterno}, apellido_materno=#{apellidoMaterno},
       calle=#{calle}, numero=#{numero}, colonia=#{colonia}, codigo_postal=#{codigoPostal}, telefono=#{telefono}, correo_electronico=#{correoElectronico}
WHERE id_cliente = #{idCliente}
